  for (const at of [12, 27, 16, 23]) {
    windowBay(g, "north", 10, at, 2, 5, 4, { sill: true });
    windowBay(g, "north", 10, at, 2, 11, 4);
    flatArch(g, "north", 10, at, at + 1, 9);
